def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    emit(out, "Start: the grid contains several 3-cell L-shapes, each filling 3 of the 4 cells of a 2x2 box.")
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        filled = []
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if g[y, x] == bg:
                    out[y, x] = 1
                    filled.append((y, x))
        if filled:
            emit(out, f"Complete the L-shape in box {o['box']} by colouring its missing corner {filled[0]} with 1.")
    emit(out, "Final: every L-shape has its missing corner marked with colour 1.")
    return out
